  -- ── issue mappings ────────────────────────────────────────────────────────
  -- Curated in db/vr-issue-seed.json with a rationale and an https primary source on every
  -- row — scripts/test-mapping-discipline.mjs requires both — and argued in db/vr-federal-mapping-seed-f2.json,
  -- which also records every refusal. ON CONFLICT (measure_id, issue_key) DO NOTHING, so a
  -- re-emission cannot rewrite a rationale (runbook rule 21).

  -- H.R. 6644 (119th): NO MAPPING FROM THIS PASS, and that is the decision.
  --   PURE ATTRIBUTION. No mapping is added, changed or removed. The measure's four live
  --   rows (housing_build w100 PRIMARY, housing w80, permitting_reform w60, crypto_cbdc
  --   w40) are all correct and all stay exactly as an earlier pass wrote them, rationales
  --   included. What this wave gives the measure is the missing half of its own vote: the
  --   Senate passed the standalone bill 89-10 and the record held only the House
  --   concurrence. The migration pins the row count at 4 so a later pass cannot re-stuff
  --   the measure while landing an attribution.

  -- S.J.Res. 10 (119th) — energy_production yea_opposes w90 PRIMARY
  --   Federal wave F2. A privileged National Emergencies Act termination resolution — 50
  --   U.S.C. 1622(c) — read from its introduced text, which is one operative sentence.
  --   Filed on the SUBJECT axis with no process secondary, following S.J.Res. 37 and H.J.
  --   Res. 46; congress_oversight was read and refused. See
  --   db/vr-federal-mapping-seed-f2.json for the argument, the near-unanimity and
  --   two-flank checks, and — for S.J.Res. 71 — why the same text voted twice is admitted
  --   as two acts.
  --   Read and refused on this measure: congress_oversight. The argument against each is
  --   in db/vr-federal-mapping-seed-f2.json.
  --   decisiveQuestion: 'On the Joint Resolution' on an S.J.Res. is the single entry in
  --   rule 12's PASSAGE_FORMS. Admitted on the form alone, so no decisiveWhy is written.
  --   singleSubject: Read from the introduced text (govinfo BILLS-119sjres10is), which is
  --   one operative sentence in full: 'That the national emergency relating to energy
  --   declared on January 20, 2025, by the President in Executive Order 14156 (90 Fed.
  --   Reg. 8433) and pursuant to the National Emergencies Act (50 U.S.C. 1601 et seq.), is
  --   terminated.' There is no second subject, no reserve fund, no sense-of-the-Senate
  --   clause and no severable provision. Rule 31 does not reach it: the operative verb is
  --   'is terminated', not 'consider'.
  --   notReserveFund: Correct. Rule 31's three textual tells — 'To establish a
  --   deficit-neutral reserve fund relating to…', 'To make sure the Senate can…', and an
  --   operative verb of 'consider' — are all absent. This is a privileged joint resolution
  --   under 50 U.S.C. 1622(c), which if enacted terminates the emergency by operation of
  --   law.
  --   proceduralInversion: No. The question is the resolution itself, so
  --   yeaBlocksMeasure() does not fire and the ordinary direction holds: a yea advances
  --   the resolution.
  --   nearUnanimity: No. 47-52 with one senator not voting. The losing side is 47.475% of
  --   the yea+nay pool, far above the one-tenth bar. Party totals from the document
  --   itself: D 45-0 yea, I 2-0 yea, R 0-52 nay.
  --   twoFlankNays: Checked (rule 5 / rule 23) and NO. The 52 nays are 52 Republicans —
  --   one bloc with one argument, that the emergency should stand. There is no second
  --   flank arguing the resolution does not go far enough, so the headline key stands and
  --   no provision-level substitution is needed.
  --   enactedTier: Not law. Rejected on the Senate floor 2025-02-26 and never reached the
  --   House. Filed status 'rejected_senate'.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_j_res_10, 'energy_production', 90, true, 'yea_opposes',
      'The resolution''s whole operative text terminates the national energy emergency declared in Executive Order 14156, and that order is already in this record as energy_production w100 PRIMARY yea_supports for ''directing agencies to use emergency authorities to expedite domestic energy production''. Terminating it withdraws exactly those authorities, so a yea cuts against expanded domestic production and the row is coded yea_opposes. Weight 90 rather than 100 because the instrument reaches the emergency authorities alone and not the separate permitting and leasing apparatus of Executive Order 14154, which the record scores on its own. The corpus already files an emergency-termination joint resolution this way: H.J. Res. 46, on the February 2019 border emergency, carries border_security w90 PRIMARY yea_opposes as its single row — same instrument class, same weight, same polarity logic, and likewise no secondary for the National Emergencies Act process itself.',
      'https://www.govinfo.gov/content/pkg/BILLS-119sjres10is/html/BILLS-119sjres10is.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S.J.Res. 71 (119th) — energy_production yea_opposes w90 PRIMARY
  --   Federal wave F2. A privileged National Emergencies Act termination resolution — 50
  --   U.S.C. 1622(c) — read from its introduced text, which is one operative sentence.
  --   Filed on the SUBJECT axis with no process secondary, following S.J.Res. 37 and H.J.
  --   Res. 46; congress_oversight was read and refused. See
  --   db/vr-federal-mapping-seed-f2.json for the argument, the near-unanimity and
  --   two-flank checks, and — for S.J.Res. 71 — why the same text voted twice is admitted
  --   as two acts.
  --   decisiveQuestion: Same as S.J.Res. 10: 'On the Joint Resolution' on an S.J.Res.,
  --   rule 12's one PASSAGE_FORMS entry, no decisiveWhy needed.
  --   singleSubject: The introduced text (govinfo BILLS-119sjres71is) is word-for-word
  --   identical to S.J.Res. 10's, terminating the same Executive Order 14156 emergency.
  --   Same single operative sentence, same subject.
  --   whyBothAreAdmitted: DISCLOSED, because it is the one thing about this pair a reader
  --   could reasonably object to. The two resolutions are the same text voted twice: 50
  --   U.S.C. 1622(b) re-privileges a termination resolution every six months, which is how
  --   Kaine and Heinrich forced a second floor vote in October after February's failed.
  --   Among senators who actually cast a yea or nay, the two rolls are IDENTICAL — the yea
  --   sets match exactly, member for member. The only differences are absences, and they
  --   cut both ways: kevin_cramer was Not Voting on roll 95 and voted nay on roll 554,
  --   while cruz and sheehy voted nay on roll 95 and were Not Voting on roll 554. So each
  --   roll is the sole record of some senator's position on this question, and admitting
  --   only one would leave a senator unrecorded on a fight they took a side in. Admitting
  --   both is therefore not depth-padding by choice: it is the only way to record all 100
  --   seats. What it does NOT do is add discrimination — no senator changed sides — and
  --   that is stated here rather than left for a reader to discover from the numbers.
  --   notReserveFund: Correct, for the same textual reasons as S.J.Res. 10. None of rule
  --   31's tells is present.
  --   proceduralInversion: No. The question is the resolution itself.
  --   nearUnanimity: No. 47-51 with two senators not voting. The losing side is 47.959% of
  --   the yea+nay pool. Party totals from the document: D 45-0 yea, I 2-0 yea, R 0-51 nay.
  --   twoFlankNays: Checked and NO — the 51 nays are 51 Republicans, one bloc, one
  --   argument.
  --   enactedTier: Not law. Rejected on the Senate floor 2025-10-08. Filed status
  --   'rejected_senate'.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_j_res_71, 'energy_production', 90, true, 'yea_opposes',
      'The resolution''s whole operative text terminates the national energy emergency declared in Executive Order 14156, which this record already scores as energy_production w100 PRIMARY yea_supports for directing agencies to use emergency authorities to expedite domestic production. Terminating it withdraws those authorities, so a yea cuts against expanded domestic production. Weight and polarity match the February companion S.J.Res. 10 because the text is identical; the two are separate acts six months apart, taken under the re-privileging clock in 50 U.S.C. 1622(b), and each is the only record of where some senators stood on the question.',
      'https://www.govinfo.gov/content/pkg/BILLS-119sjres71is/html/BILLS-119sjres71is.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- ── retraction ────────────────────────────────────────────────────────────
  -- The only DELETE in this migration, and the only place it removes a live reading.
  -- Guarded on issue_key AND weight AND is_primary AND support_meaning AND the exact
  -- rationale string. Three consequences, all wanted: a re-run removes nothing; a pass
  -- that has already rewritten this row keeps its work rather than being clobbered by a
  -- migration that has not read it; and if the live row is not what this file believes it
  -- is, the DELETE is a silent no-op instead of a wrong removal — which the verification
  -- block then catches by asserting the row is gone.

  -- H.R. 1048 (119th) — RETRACT america_first w70 yea_supports
  --   WHY: Rule 32, and the item F1 queued as follow-up 0e. The america_first chip was
  --   narrowed in August 2026 to ONE thing — what the United States funds and commits to
  --   abroad — and its scope note in alignment-tool.js puts this row's own stated ground
  --   on the OUT list by name: 'countering China and military posture toward adversaries
  --   (strong_defense, tariffs_china)'. The rationale above is that ground and nothing
  --   else. The DETERRENT Act is a domestic disclosure statute: it requires universities
  --   to report foreign gifts and contracts and enforces the duty through fines and Title
  --   IV. There is no aid level, no partner funding, no assessed contribution and no
  --   commitment wind-down anywhere in it, so the row cannot move to america_first_fp
  --   either — that chip is 'cut, condition or wind down U.S. foreign aid and open-ended
  --   commitments abroad'. A re-key would need a chip that fits, and none does. So this is
  --   a removal, which is also what follow-up 0e predicted after reading it.
  --   WHY IT IS SAFE: The measure keeps gov_transparency w100 PRIMARY — 'force disclosure
  --   of foreign money flowing to universities, faculty, and endowments', which is the
  --   bill's actual operative purpose and is untouched — and edu_balance w55. The measure
  --   does not lose its primary, does not lose its roll (house 119/1/83, 241-169), and
  --   does not leave the record. What goes away is one non-primary row on a key the
  --   vocabulary disowned, which is the whole point: a stale mapping keeps publishing,
  --   while a stale refusal publishes nothing.
  --   COST: A retraction is a subtraction and is measured like one. Removing this row
  --   lowers by one the america_first judged-act count of every member attributed on roll
  --   119/1/83, so the before/after FPI table for this wave is run over all 327 federal
  --   pids and not only the Utah seven. MEASURED RESULT: on the key itself, mixed_thin 10
  --   → 2 and incidental 99 → 101 — removing the contradicting row lets eight members'
  --   america_first records resolve and costs two. The two are dan_crenshaw and massie,
  --   whose america_first record was two judged secondary acts of which this was one; the
  --   survivor is H.R. 4 alone, and their only primary on the key is a not_voting on H.R.
  --   276, which was never a judged act for them. Named in full under readLossDisclosure.
  --   Net +6 characterised on the key whose vocabulary this fixes, and the two losses are
  --   not a reason to keep a mapping the vocabulary disowned.
  SELECT id INTO m_119_h_r_1048 FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119
     AND chamber = 'house' AND number = 'H.R. 1048' LIMIT 1;
  IF m_119_h_r_1048 IS NULL THEN
    RAISE EXCEPTION 'Federal wave F2: H.R. 1048 (119th house) is not in vr_measures, so its america_first row cannot be retracted. This measure is never created here.';
  END IF;
  DELETE FROM vr_measure_issues
   WHERE measure_id = m_119_h_r_1048 AND issue_key = 'america_first'
     AND weight = 70 AND is_primary = false
     AND support_meaning = 'yea_supports'
     AND rationale = 'Targets foreign influence — especially from China, Iran, North Korea, and Russia — on U.S. campuses as a national-security matter.';

END $$;

--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's roll calls and measures so it
-- can only ever fail on data this migration is responsible for. A global count would
-- drag in every mapping earlier passes wrote and stop meaning anything.
--
-- Member-vote counts assert >=, because ON CONFLICT DO NOTHING means an earlier
-- attribution path may already hold rows on a roll this pass touches. The orphan check
-- is exact: a politician_id on one of these rolls that is not in db/vr-member-map.json
-- is an attribution failure, not a rounding difference, and fail-closed attribution
-- means there should be none.
--
-- The specific assertions are the things this pass exists to do. Each new PRIMARY is
-- named with its polarity, so a row that landed with yea_supports instead of
-- yea_opposes is caught rather than averaged into a total. H.R. 1069 is asserted to
-- carry EXACTLY ZERO mapped rows — the only way to make a deliberate refusal testable,
-- restated here because F2 was explicitly told not to invent a key for it. And the
-- retracted row is asserted GONE, because a guarded DELETE that matched nothing is
-- indistinguishable from a successful one without this check.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_issues integer;
  n_unmapped integer;
  n_ep_senate integer;
  n_hb_senate integer;
  n_energy_production_m_119_s_j_res_10 integer;
  n_energy_production_m_119_s_j_res_71 integer;
  n_rows_m_119_h_r_6644 integer;
  n_retracted_m_119_h_r_1048 integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('senate'::text, 119::integer, 1::integer, 95::integer),
    ('senate'::text, 119::integer, 1::integer, 554::integer),
    ('senate'::text, 119::integer, 2::integer, 53::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  ), mine (measure_type, congress, chamber, number) AS (VALUES
    ('bill'::text, 119::integer, 'house'::text, 'H.R. 6644'::text),
    ('resolution'::text, 119::integer, 'senate'::text, 'S.J.Res. 10'::text),
    ('resolution'::text, 119::integer, 'senate'::text, 'S.J.Res. 71'::text)
  ), measure_ids AS (
    SELECT m.id FROM vr_measures m JOIN mine k
      ON m.measure_type = k.measure_type AND m.congress = k.congress
     AND m.chamber = k.chamber AND m.number = k.number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)
            AND v.politician_id NOT IN (
              'adam_smith', 'aguilar', 'alsobrooks', 'andy_harris', 'andy_kim', 'angie_craig', 'angus_king', 'aoc', 'arrington', 'ashley_moody', 'ayanna_pressley', 'banks', 'barrasso', 'bennet', 'bennie_thompson', 'blackburn', 'blumenthal', 'blunt_rochester', 'bmoore', 'boebert', 'booker', 'boozman', 'brendan_boyle', 'brian_babin', 'brian_mast', 'britt', 'bruce_westerman', 'bryan_steil', 'cantwell', 'capito', 'cassidy', 'chellie_pingree', 'chip_roy', 'chris_murphy', 'clyburn', 'collins', 'comer', 'coons', 'cortez_masto', 'cotton', 'crapo', 'crockett', 'cruz', 'cstewart', 'curtis', 'daines', 'dan_crenshaw', 'dan_goldman', 'dan_sullivan', 'deb_fischer', 'debbie_dingell', 'delauro', 'delia_ramirez', 'diana_degette', 'don_bacon', 'don_davis', 'donalds', 'duckworth', 'durbin', 'emmer', 'ernst', 'fetterman', 'fitzpatrick', 'foxx', 'frank_lucas', 'french_hill', 'gaetz', 'gallego', 'garbarino', 'gillibrand', 'glenn_thompson', 'graham', 'grassley', 'greg_landsman', 'guthrie', 'hagerty', 'haley_stevens', 'hawley', 'heinrich', 'hickenlooper', 'hirono', 'hoeven', 'jake_auchincloss', 'jan_schakowsky', 'jared_golden', 'jared_huffman', 'jason_smith', 'jayapal', 'jeffries', 'jerry_moran', 'jim_himes', 'jim_jordan', 'jim_justice', 'jim_mcgovern', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'kevin_cramer', 'kevin_hern', 'khanna', 'klobuchar', 'lankford', 'lee', 'lujan', 'lummis', 'luna', 'maggie_hassan', 'maloy', 'mariannette_miller_meeks', 'marie_gluesenkamp_perez', 'mark_kelly', 'markey', 'massie', 'maxine_waters', 'maxwell_frost', 'mcclain', 'mcconnell', 'mccormick', 'meeks', 'merkley', 'michael_guest', 'mike_bost', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_rounds', 'mike_simpson', 'mike_waltz', 'moreno', 'mtg', 'mullin', 'murkowski', 'murray', 'nadler', 'nancy_mace', 'neal', 'neguse', 'omar', 'owens', 'padilla', 'pallone', 'peters', 'raja_krishnamoorthi', 'rand_paul', 'raskin', 'reed', 'rick_crawford', 'rick_larsen', 'rick_scott', 'ricketts', 'risch', 'rob_bresnahan', 'robert_garcia', 'roger_marshall', 'roger_williams', 'ron_johnson', 'rosen', 'rubio', 'ryan_mackenzie', 'sam_graves', 'sanders', 'sarah_mcbride', 'scalise', 'schatz', 'schiff', 'schmitt', 'schumer', 'scott_perry', 'seth_moulton', 'shaheen', 'sheehy', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'takano', 'tammy_baldwin', 'ted_budd', 'ted_lieu', 'tgabbard', 'thune', 'tillis', 'tim_scott', 'tina_smith', 'tlaib', 'todd_young', 'tom_cole', 'tom_suozzi', 'tommy_tuberville', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'walberg', 'warner', 'warnock', 'warren', 'welch', 'whitehouse', 'wicker', 'wyden', 'zeldin', 'zoe_lofgren'
            )),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.measure_id IN (SELECT id FROM measure_ids)
            AND i.issue_key IN ('energy_production'))
    INTO n_rolls, n_votes, n_orphan, n_issues;

  SELECT count(*) INTO n_energy_production_m_119_s_j_res_10 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate'
     AND m.number = 'S.J.Res. 10' AND i.issue_key = 'energy_production'
     AND i.is_primary AND i.weight = 90 AND i.support_meaning = 'yea_opposes';
  SELECT count(*) INTO n_energy_production_m_119_s_j_res_71 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate'
     AND m.number = 'S.J.Res. 71' AND i.issue_key = 'energy_production'
     AND i.is_primary AND i.weight = 90 AND i.support_meaning = 'yea_opposes';
  SELECT count(*) INTO n_rows_m_119_h_r_6644 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.R. 6644';
  SELECT count(*) INTO n_retracted_m_119_h_r_1048 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house'
     AND m.number = 'H.R. 1048' AND i.issue_key = 'america_first';
  SELECT count(*) INTO n_unmapped FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.R. 1069';
  SELECT count(*) INTO n_ep_senate FROM vr_rollcalls r
    JOIN vr_measure_issues i ON i.measure_id = r.measure_id
   WHERE r.chamber = 'senate' AND i.issue_key = 'energy_production' AND i.is_primary;
  SELECT count(*) INTO n_hb_senate FROM vr_rollcalls r
    JOIN vr_measure_issues i ON i.measure_id = r.measure_id
   WHERE r.chamber = 'senate' AND i.issue_key = 'housing_build' AND i.is_primary;

  RAISE NOTICE 'Federal wave F2: % roll calls, % member votes, % issue mappings', n_rolls, n_votes, n_issues;
  RAISE NOTICE 'Federal wave F2: H.R. 1069 carries % mapped issue row(s)', n_unmapped;
  RAISE NOTICE 'Federal wave F2: % senate roll(s) now sit on an energy_production PRIMARY measure, % on a housing_build PRIMARY measure', n_ep_senate, n_hb_senate;
  RAISE NOTICE 'Federal wave F2: H.R. 1048 carries % america_first row(s) after the retraction', n_retracted_m_119_h_r_1048;
  RAISE NOTICE 'Federal wave F2: H.R. 6644 carries % mapped issue row(s)', n_rows_m_119_h_r_6644;

  IF n_rolls <> 3 THEN
    RAISE EXCEPTION 'Federal wave F2: expected 3 roll calls, found %', n_rolls;
  END IF;
  IF n_votes < 294 THEN
    RAISE EXCEPTION 'Federal wave F2: expected at least 294 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Federal wave F2: % member vote(s) on these rolls carry a politician_id outside db/vr-member-map.json. Attribution here is fail-closed, so this is a bug, not a roster gap.', n_orphan;
  END IF;
  IF n_issues < 2 THEN
    RAISE EXCEPTION 'Federal wave F2: expected at least 2 issue mappings on this pass''s measures, found %', n_issues;
  END IF;
  IF n_energy_production_m_119_s_j_res_10 <> 1 THEN
    RAISE EXCEPTION 'Federal wave F2: the energy_production w90 PRIMARY yea_opposes row on S.J.Res. 10 (119th) did not land (found % row(s)). Polarity matters here: EO 14156 carries this key yea_supports, and these resolutions terminate it.', n_energy_production_m_119_s_j_res_10;
  END IF;
  IF n_energy_production_m_119_s_j_res_71 <> 1 THEN
    RAISE EXCEPTION 'Federal wave F2: the energy_production w90 PRIMARY yea_opposes row on S.J.Res. 71 (119th) did not land (found % row(s)). Polarity matters here: EO 14156 carries this key yea_supports, and these resolutions terminate it.', n_energy_production_m_119_s_j_res_71;
  END IF;
  IF n_retracted_m_119_h_r_1048 <> 0 THEN
    RAISE EXCEPTION 'Federal wave F2: H.R. 1048 still carries % america_first row(s). The guarded DELETE matched nothing, which means the live row is not the value this migration read. Re-read it before forcing the removal — see db/vr-federal-mapping-seed-f2.json.', n_retracted_m_119_h_r_1048;
  END IF;
  IF n_rows_m_119_h_r_6644 <> 4 THEN
    RAISE EXCEPTION 'Federal wave F2: H.R. 6644 carries % mapped issue row(s), expected exactly 4. This pass adds an attribution to this measure and deliberately adds NO mapping; a changed count means somebody re-stuffed the measure to feed coverage.', n_rows_m_119_h_r_6644;
  END IF;
  IF n_unmapped <> 0 THEN
    RAISE EXCEPTION 'Federal wave F2: H.R. 1069 is deliberately unmapped and now carries % issue row(s). F1 refused nine candidate keys in writing and F2 re-refused them; see db/vr-federal-mapping-seed-f1.json before adding one.', n_unmapped;
  END IF;
  IF n_ep_senate < 2 THEN
    RAISE EXCEPTION 'Federal wave F2: the Senate holds only % decisive roll(s) on an energy_production PRIMARY measure. Below 2 the primary wall in stance-helpers.js reopens and senators read as not-about-this-issue on a key they have voted on repeatedly.', n_ep_senate;
  END IF;
  IF n_hb_senate < 1 THEN
    RAISE EXCEPTION 'Federal wave F2: the Senate holds only % decisive roll(s) on a housing_build PRIMARY measure, so housing_build is back to vehicle_only for the whole Senate caucus. H.R. 6644''s Senate roll is the only instrument in the 119th that closes it.', n_hb_senate;
  END IF;
END $$;
